  /* ===================== FLASHCARDS ===================== */
  flashcards: [
    { id: "fc01", categoria: "concepto", frente: "MLN-T", dorso: "Movimiento de Liberación Nacional-Tupamaros. Guerrilla urbana (Montevideo), de clase media, que actuó contra una democracia (1963–72). «Tupamaros» viene de Túpac Amaru II." },
    { id: "fc02", categoria: "concepto", frente: "Ideología del MLN", dorso: "Nacionalistas de izquierda, pragmáticos, urbanos (Artigas, no Lenin): «las palabras nos separan, la acción nos une». No eran leninistas ortodoxos; el PCU los criticaba." },
    { id: "fc03", categoria: "concepto", frente: "«Acción–represión–acción»", dorso: "Documento 1 (1967): cada acción provoca represión que (en teoría) radicaliza al pueblo. Funcionó al revés: radicalizó al Estado." },
    { id: "fc04", categoria: "concepto", frente: "Cárcel del Pueblo", dorso: "Sótano clandestino con rehenes (Jackson, Pereira Reverbel) y «juicios populares». Símbolo del «poder dual». Descubierta el 27-V-1972." },
    { id: "fc05", categoria: "concepto", frente: "Las cuatro fases del MLN", dorso: "Silenciosa (1963–67), propaganda armada/Robin Hood (1968–69), escalada (1970–71), «guerra» y derrota (1972)." },
    { id: "fc06", categoria: "concepto", frente: "«Teoría de los dos demonios»", dorso: "Pone en pie de igualdad la violencia guerrillera y la estatal. Demasi la llama «simplista» y «casi mecánica». Criticarla en la conclusión suma banda." },
    { id: "fc07", categoria: "fecha", frente: "1961", dorso: "Sendic organiza la UTAA (cañeros de Bella Unión): la raíz social del MLN." },
    { id: "fc08", categoria: "fecha", frente: "1962", dorso: "Fracaso electoral de la izquierda (Unión Popular 2,3%; FIDEL 3,5%): un sector concluye «las urnas no sirven»." },
    { id: "fc09", categoria: "fecha", frente: "31-VII-1963", dorso: "Asalto al Tiro Suizo: nace de hecho el MLN; Sendic a la clandestinidad." },
    { id: "fc10", categoria: "fecha", frente: "ene. 1966", dorso: "Convención fundacional: nombre MLN. 22-XII-1966: primer muerto (Carlos Flores)." },
    { id: "fc11", categoria: "fecha", frente: "7-VIII-1968", dorso: "Primer secuestro: Pereira Reverbel. Inicio de la propaganda armada." },
    { id: "fc12", categoria: "fecha", frente: "feb. 1969", dorso: "Financiera Monti: se llevan los libros y prueban la corrupción de políticos." },
    { id: "fc13", categoria: "fecha", frente: "8-X-1969", dorso: "Toma de Pando: punto de inflexión (primera operación militar y primeras muertes propias, Marchesi)." },
    { id: "fc14", categoria: "fecha", frente: "10-VIII-1970", dorso: "Ejecución de Dan Mitrione: les cuesta la simpatía moderada y da a Pacheco el argumento de «guerra»." },
    { id: "fc15", categoria: "fecha", frente: "8-I-1971", dorso: "Secuestro del embajador británico Jackson (8 meses en la Cárcel del Pueblo)." },
    { id: "fc16", categoria: "fecha", frente: "6-IX-1971", dorso: "Fuga «El Abuso»: 111 presos de Punta Carretas por un túnel. Provoca las Fuerzas Conjuntas (9-IX)." },
    { id: "fc17", categoria: "fecha", frente: "14-IV-1972", dorso: "El MLN mata a 4 del Escuadrón de la Muerte; mueren 8 tupamaros. 15-IV: estado de guerra interno. Empieza la «guerra» y la derrota." },
    { id: "fc18", categoria: "fecha", frente: "1-IX-1972", dorso: "Cae Sendic (herido en la cara). En 7 meses el MLN pasa de 3.000 a cero." },
    { id: "fc19", categoria: "causa-consecuencia", frente: "¿De dónde nace el MLN?", dorso: "De la crisis social del norte azucarero (cañeros, UTAA) y de la frustración electoral de 1962. Producto de la crisis, no su causa (Demasi, Marchesi)." },
    { id: "fc20", categoria: "causa-consecuencia", frente: "¿Por qué el MLN creció tras 1968?", dorso: "La represión de Pacheco y la muerte de Líber Arce empujaron a estudiantes y clase media hacia la guerrilla: el Estado fue «el mejor reclutador»." },
    { id: "fc21", categoria: "causa-consecuencia", frente: "¿Por qué pierde el MLN en 1972?", dorso: "Militarización sin capacidad militar: subestimaron a las FF.AA. y sobreestimaron la crisis. Derrotados en 7 meses; tortura y traición de Amodio." },
    { id: "fc22", categoria: "causa-consecuencia", frente: "Efecto contrario del MLN", dorso: "Legitimó a las FF.AA. y la DSN y dio el argumento del «estado de guerra»; sin quererlo, metió a los militares en la política (Fuerzas Conjuntas 1971)." },
    { id: "fc23", categoria: "causa-consecuencia", frente: "Paradoja de largo plazo", dorso: "Derrotado en 1972, el MLN gobernó el país en 2010 (MPP, Mujica): «derrotados militarmente, exitosos generacionalmente» (Marchesi)." },
    { id: "fc24", categoria: "historiador", frente: "Marchesi (postura 14.6)", dorso: "Nueva izquierda transnacional del Cono Sur; la militarización de 1970–72 fue el error decisivo que lo derrotó y legitimó a las FF.AA. Síntesis entre Sanguinetti y Demasi." },
    { id: "fc25", categoria: "historiador", frente: "Demasi (postura 14.6)", dorso: "El MLN fue producto de la crisis, no su causa; pretexto, no causa del golpe (MPS 1968 sin Tupamaros; represión creció tras derrotarlo). Rechaza los «dos demonios»." },
    { id: "fc26", categoria: "historiador", frente: "Sanguinetti (postura 14.6)", dorso: "El MLN, al alzarse contra una democracia electoral, fue el principal desestabilizador; «enceguecido», entregó el país a los militares." },
    { id: "fc27", categoria: "historiador", frente: "Caetano y Rilla (sobre el MLN)", dorso: "La derrota del MLN en 1972 desplazó el poder real a los cuarteles: militares «triunfadores» que no volvieron." },
    { id: "fc28", categoria: "historiador", frente: "Mujica (frase regalo)", dorso: "La violencia de fines de los 60 se explica desde la crisis y la cultura de la época, no solo por la acción tupamara. «Las dos memorias»: Sanguinetti vs. Mujica." },
    { id: "fc29", categoria: "concepto", frente: "El FA no era el brazo del MLN", dorso: "El Frente Amplio (1971) fue coalición electoral con Seregni crítico de la lucha armada; solo el Movimiento 26 de Marzo era afín. La tregua de 1971 fue unilateral." },
    { id: "fc30", categoria: "concepto", frente: "Responsabilidad del MLN en el golpe", dorso: "Del cómo y del cuándo (llevó a las FF.AA. al centro), no del por qué (crisis 1955, MPS 1968). En una medida menor de la que la memoria dominante le asigna." }
  ],

